update.foreach:
update T_GSQ_SCHEDULE_RESULT
set BATCH_NO = #{item.batchNo}, ORDER_NO = #{item.orderNo}
where ID = #{item.id}

mapper.select:
select FACTORY_CODE as factoryCode, MIN_MACHINE_QTY as minMachineQty, MAX_MACHINE_QTY as maxMachineQty, DEPTH_CLASS_QTY as depthClassQty from T_GSQ_STOCK_SHIFT_CONFIG where IS_DELETE = '0'
and FACTORY_CODE = #{factoryCode}
order by MIN_MACHINE_QTY
